{
  "name": "@sffmc/utilities",
  "version": "0.16.5",
  "category": "sffmc-original",
  "type": "module",
  "main": "src/index.ts",
  "scripts": {
    "test": "bun test",
    "build": "tsc --noEmit",
    "test:watch": "bun test --watch",
    "typecheck": "bun build --target=bun --no-bundle src/index.ts"
  },
  "dependencies": {
    "valibot": "^0.42.1",
    "yaml": "^2.0.0"
  },
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/Rahspide/sffmc.git",
    "directory": "packages/utilities"
  },
  "publishConfig": {
    "access": "public",
    "registry": "https://registry.npmjs.org/"
  },
  "files": [
    "README.md",
    "package.json",
    "src/**/*.ts"
  ],
  "description": "Shared SDK library for SFFMC plugins — loadConfig, mergeHooks, EventBus, FsOps, redactSecrets. Not a plugin entry; consumed via workspace:* by the other 4 packages.",
  "keywords": [
    "sffmc",
    "opencode",
    "sdk",
    "library",
    "plugin-infrastructure"
  ],
  "bugs": {
    "url": "https://github.com/Rahspide/sffmc/issues"
  },
  "homepage": "https://github.com/Rahspide/sffmc/tree/main/packages/utilities#readme"
}
